<script setup lang="ts">
import {computed,ref} from 'vue';import {useRouter} from 'vue-router';import {IconGridDots,IconSparkles,IconCube,IconClock} from '@tabler/icons-vue'
import Panel from '../components/Panel.vue';import {seals,events,select,current,kindName,date,api,run,refresh,notify,isProcessImage} from '../store'
const router=useRouter();const editing=ref('');const title=ref('');const artifacts=computed(()=>seals.value.flatMap(s=>s.artifacts));const models=computed(()=>artifacts.value.filter(a=>a.kind==='stl'))
function open(id:string){select(id);router.push('/recognition')};function edit(id:string,name:string){editing.value=id;title.value=name}
async function save(){await run(async()=>{await api('/seals/'+editing.value,{method:'PATCH',body:JSON.stringify({title:title.value})});editing.value='';await refresh();notify('项目名称已保存。')})}
const action:Record<string,string>={upload:'添加原始印谱扫描',extract:'完成印文提取',clean:'生成去噪版本',repair:'完成OpenCV修复',restoration:'完成AI修复',recognition:'完成AI识别',reconstruct:'生成三维印面模型',review:'人工选择处理版本',manufacturing:'保存实体制作记录',rename:'更新项目名称',culture_answer:'完成文化助手问答',corpus_import:'载入本机印谱裁图',enhancement:'生成实验去噪版本',annotation_draft:'保存人工标注草稿'}
</script>
<template><div class="metrics project-metrics"><article><span>实际印谱数量<IconGridDots/></span><strong>{{seals.length}}</strong></article><article><span>已生成处理版本<IconSparkles/></span><strong>{{artifacts.filter(a=>isProcessImage(a)&&a.kind!=='original').length}}</strong></article><article><span>模型制造任务<IconCube/></span><strong>{{models.length}}</strong></article><article><span>处理审计记录<IconClock/></span><strong>{{events.length}}</strong></article></div><div class="projects-grid"><Panel title="我的印谱复原项目" note="多版本存档 · 操作审计 · 制作记录"><div class="table-scroll"><table><thead><tr><th>项目名称</th><th>更新时间</th><th>最新版本</th><th>所属模块</th><th>当前状态</th><th>快捷操作</th></tr></thead><tbody><tr v-for="s in seals" :key="s.id"><td><img :src="s.original_url" alt="">{{s.title}}</td><td>{{date(s.artifacts.at(-1)?.created_at||s.created_at).split(' ')[0]}}</td><td>{{kindName[s.artifacts.at(-1)?.kind||'original']}}</td><td>{{s.source_kind==='synthetic_test'?'合成测试':s.source_kind==='local_corpus'?'本机素材':'用户上传'}}</td><td><span class="pill">{{s.artifacts.length>1?'已处理':'待处理'}}</span></td><td><button class="text-button" @click="open(s.id)">查看</button><button class="text-button" @click="edit(s.id,s.title)">编辑</button></td></tr></tbody></table><div v-if="!seals.length" class="empty-state">尚未创建印谱项目。<RouterLink to="/upload">上传第一张印谱 →</RouterLink></div></div></Panel><Panel title="近期处理时间线" note="可追踪的复原过程与来源"><ol class="timeline"><li v-for="(e,i) in events.slice(0,4)" :key="e.id"><b>{{i+1}}</b><div><strong>{{action[e.action]||e.action}}</strong><small>{{date(e.created_at)}}</small><small>{{seals.find(s=>s.id===e.seal_id)?.title||'知识问答'}}</small></div></li></ol><p v-if="!events.length" class="hint">暂无操作记录。</p></Panel></div><Panel class="asset-panel" title="数字资产与版本管理" note="数据库存取 · 可溯源历史记录"><div class="asset-grid"><RouterLink to="/upload"><h4>原始图像资产</h4><p>扫描件与文献索引</p><strong>{{artifacts.filter(a=>a.kind==='original').length}} 个原始文件</strong></RouterLink><RouterLink to="/restoration"><h4>图像处理版本</h4><p>原图保留与真实处理产物</p><strong>{{artifacts.filter(a=>isProcessImage(a)&&a.kind!=='original').length}} 个版本</strong></RouterLink><RouterLink to="/reconstruction"><h4>三维制造资产</h4><p>真实STL与网格检查记录</p><strong>{{models.length}} 个模型</strong></RouterLink></div></Panel><div v-if="editing" class="modal-backdrop" @click.self="editing=''"><form class="modal" @submit.prevent="save"><h2>编辑印谱项目</h2><label>项目名称<input v-model="title" required maxlength="150" aria-label="项目名称"></label><div class="actions"><button class="primary">保存</button><button type="button" @click="editing=''">取消</button></div></form></div></template>
